// Images des circuits Mérine (panneaux savane) — générées par Amany.
// Base64 pour être versionnées malgré le filtre .gitignore sur les *.png.
export const CIRCUIT_IMAGES: Record<string, string> = {
  "MER-AUT": "data:image/png;base64,",
  "MER-ELE": "data:image/png;base64,",
  "MER-GIR": "data:image/png;base64,",
  "MER-GNO": "data:image/png;base64,",
  "MER-HIP": "data:image/png;base64,",
  "MER-LEO": "data:image/png;base64,",
  "MER-LIO": "data:image/png;base64,",
  "MER-ZEB": "data:image/png;base64,",
};

export function circuitImage(circuitId?: string): string | undefined {
  return circuitId ? CIRCUIT_IMAGES[circuitId] : undefined;
}